import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'analytics',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: false },
  max: 20
});

// Middleware: basic API key check
app.use((req, res, next) => {
  const key = req.headers['x-api-key'];
  if (!key || key.length < 16) return res.status(401).json({ error: 'unauthorized' });
  next();
});

// User search endpoint - uses parameterized query (SAFE)
app.get('/api/users', async (req, res) => {
  const { name, department } = req.query;
  const result = await pool.query(
    'SELECT id, name, email, department FROM users WHERE name ILIKE $1 AND department = $2 LIMIT 50',
    [`%${name}%`, department]
  );
  res.json(result.rows);
});

// Report generation - dynamic table selection (VULNERABLE)
app.get('/api/reports/:reportType', async (req, res) => {
  const { reportType } = req.params;
  const { startDate, endDate, groupBy } = req.query;

  // Validate reportType against allowlist
  const allowedReports = ['sales', 'inventory', 'traffic', 'conversions'];
  if (!allowedReports.includes(reportType)) {
    return res.status(400).json({ error: 'invalid report type' });
  }

  // Validate date format
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(startDate) || !dateRegex.test(endDate)) {
    return res.status(400).json({ error: 'invalid date format' });
  }

  // groupBy is user-controlled and directly interpolated (VULNERABLE)
  // Developer assumed groupBy would be a column name
  const query = `
    SELECT ${groupBy}, COUNT(*) as count, SUM(amount) as total
    FROM report_${reportType}
    WHERE created_at BETWEEN $1 AND $2
    GROUP BY ${groupBy}
    ORDER BY total DESC
    LIMIT 100
  `;

  try {
    const result = await pool.query(query, [startDate, endDate]);
    res.json({ report: reportType, data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'query failed', detail: err.message });
  }
});

// Export endpoint - writes CSV to disk
app.post('/api/export', async (req, res) => {
  const { query_id } = req.body;
  const sanitizedId = query_id.replace(/[^a-f0-9-]/g, '');
  const filename = `/tmp/export_${sanitizedId}.csv`;

  const result = await pool.query(
    'SELECT * FROM cached_results WHERE query_id = $1', [sanitizedId]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });

  const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
  fs.writeFileSync(filename, csv);
  res.json({ file: filename, rows: result.rows.length });
});

// Health check with version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1', node: process.version });
});

app.listen(3000, () => console.log('Analytics API listening on :3000'));
